import React from "react";
import PropTypes from "prop-types";

import { Button } from "@traveloka/soya-components";
import DropdownInput from "./DropdownInput";

import * as style from "./CommonRule.styles";

class OperatorModal extends React.Component {
  constructor(props) {
    super(props);
    this.state = { operator: props.operator };
  }

  handleChangeValue = (name, value) => {
    this.setState({ operator: value });
  };

  handleCancel = () => {
    const { onCancel } = this.props;
    onCancel();
  };

  handleSave = () => {
    const { onSave } = this.props;
    const { operator } = this.state;
    onSave(operator);
  };

  render() {
    const { operator } = this.state;
    const operatorItems = [
      { value: "And", label: "And" },
      { value: "Or", label: "Or" },
      { value: "Not", label: "Not" },
    ];
    return (
      <div>
        <label>{"Operator"}</label>
        <br />
        <DropdownInput
          name={"operator"}
          items={operatorItems}
          value={operator}
          onChange={this.handleChangeValue}
        />
        <div className={style.modalFooter}>
          <Button onClick={this.handleCancel} color="link">
            {"Close"}
          </Button>
          <Button onClick={this.handleSave} color="blue">
            {"OK"}
          </Button>
        </div>
      </div>
    );
  }
}

OperatorModal.propTypes = {
  operator: PropTypes.string,
  onCancel: PropTypes.func.isRequired,
  onSave: PropTypes.func.isRequired,
};

export default OperatorModal;
